def test_query_folder_contents_pager(transport_name: str = "grpc"):
    client = DataformClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.query_folder_contents), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            dataform.QueryFolderContentsResponse(
                entries=[
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                ],
                next_page_token="abc",
            ),
            dataform.QueryFolderContentsResponse(
                entries=[],
                next_page_token="def",
            ),
            dataform.QueryFolderContentsResponse(
                entries=[
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                ],
                next_page_token="ghi",
            ),
            dataform.QueryFolderContentsResponse(
                entries=[
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                    dataform.QueryFolderContentsResponse.FolderContentsEntry(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("folder", ""),)),
        )
        pager = client.query_folder_contents(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(
            isinstance(i, dataform.QueryFolderContentsResponse.FolderContentsEntry)
            for i in results
        )


