    with (
        mock.patch.object(
            google.auth, "load_credentials_from_file", autospec=True
        ) as load_creds,
        mock.patch(
            "google.cloud.dataform_v1.services.dataform.transports.DataformTransport._prep_wrapped_messages"
        ) as Transport,
    ):
        Transport.return_value = None
