@pytest.mark.parametrize(
    "transport_name",
    [
        "rest",
    ],
)
def test_dataform_client_transport_session_collision(transport_name):
    creds1 = ga_credentials.AnonymousCredentials()
    creds2 = ga_credentials.AnonymousCredentials()
    client1 = DataformClient(
        credentials=creds1,
        transport=transport_name,
    )
    client2 = DataformClient(
        credentials=creds2,
        transport=transport_name,
    )
    session1 = client1.transport.get_team_folder._session
    session2 = client2.transport.get_team_folder._session
    assert session1 != session2
    session1 = client1.transport.create_team_folder._session
    session2 = client2.transport.create_team_folder._session
    assert session1 != session2
    session1 = client1.transport.update_team_folder._session
    session2 = client2.transport.update_team_folder._session
    assert session1 != session2
    session1 = client1.transport.delete_team_folder._session
    session2 = client2.transport.delete_team_folder._session
    assert session1 != session2
    session1 = client1.transport.delete_team_folder_tree._session
    session2 = client2.transport.delete_team_folder_tree._session
    assert session1 != session2
    session1 = client1.transport.query_team_folder_contents._session
    session2 = client2.transport.query_team_folder_contents._session
    assert session1 != session2
    session1 = client1.transport.search_team_folders._session
    session2 = client2.transport.search_team_folders._session
    assert session1 != session2
    session1 = client1.transport.get_folder._session
    session2 = client2.transport.get_folder._session
    assert session1 != session2
    session1 = client1.transport.create_folder._session
    session2 = client2.transport.create_folder._session
    assert session1 != session2
    session1 = client1.transport.update_folder._session
    session2 = client2.transport.update_folder._session
    assert session1 != session2
    session1 = client1.transport.delete_folder._session
    session2 = client2.transport.delete_folder._session
    assert session1 != session2
    session1 = client1.transport.delete_folder_tree._session
    session2 = client2.transport.delete_folder_tree._session
    assert session1 != session2
    session1 = client1.transport.query_folder_contents._session
    session2 = client2.transport.query_folder_contents._session
    assert session1 != session2
